"use client";
import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import Image from 'next/image';

const Navbar = () => {
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <nav className={`fixed top-0 left-0 w-full z-50 transition-all duration-500 ${
      isScrolled ? 'bg-white shadow-md py-2' : 'bg-transparent py-4'
    }`}>
      <div className='max-w-7xl mx-auto px-6 flex justify-between items-center'>
        
        {/* LOGO */}
        <Link href="/" className='flex items-center gap-3'>
          <Image src="/westgateLogo.png" alt="Logo" width={45} height={45} />
          <span className={`font-black text-xl tracking-tighter ${isScrolled ? 'text-black' : 'text-white'}`}>
            SINDJELIC FC
          </span>
        </Link>

        {/* LINKS */}
        <ul className={`hidden md:flex gap-8 font-bold text-sm uppercase ${isScrolled ? 'text-black' : 'text-white'}`}>
          <li className='hover:text-red-600 transition cursor-pointer'><Link href="/news">News</Link></li>
          <li className='hover:text-red-600 transition cursor-pointer'><Link href="/men">Men</Link></li>
          <li className='hover:text-red-600 transition cursor-pointer'><Link href="/women">Women</Link></li>
          <li className='hover:text-red-600 transition cursor-pointer'><Link href="/juniors">Juniors</Link></li>
        </ul>
      </div>
    </nav>
  );
};

export default Navbar;